   549  /**
   550   * Return number of elements in a string including the last (zeroed) element
   551   */
   552  _PUBLIC_ uint32_t ndr_string_length(const void *_var, uint32_t element_size)
   553  {
   554          uint32_t i;
   555          uint8_t zero[4] = {0,0,0,0};
   556          const char *var = (const char *)_var;
   557
   558          for (i = 0; memcmp(var+i*element_size,zero,element_size) != 0; i++);
   559
   560          return i+1;
   561  }
