   585  _PUBLIC_ enum ndr_err_code ndr_pull_charset(struct ndr_pull *ndr, int ndr_flags, const char **var, uint32_t length, uint8_t byte_mul, charset_t chset)
   586  {
   587          size_t converted_size;
   588
   589          if (length == 0) {
   590                  *var = talloc_strdup(ndr->current_mem_ctx, "");
   591                  return NDR_ERR_SUCCESS;
   592          }
   593
   594          if (NDR_BE(ndr) && chset == CH_UTF16) {
   595                  chset = CH_UTF16BE;
   596          }
   597
   598          if ((byte_mul != 0) && (length > UINT32_MAX/byte_mul)) {
   599                  return ndr_pull_error(ndr, NDR_ERR_BUFSIZE, "length overflow");
   600          }
   601          NDR_PULL_NEED_BYTES(ndr, length*byte_mul);
   602
   603          if (!convert_string_talloc(ndr->current_mem_ctx, chset, CH_UNIX,
   604                                     ndr->data+ndr->offset, length*byte_mul,
   605                                     discard_const_p(void *, var),
   606                                     &converted_size))
   607          {
   608                  return ndr_pull_error(ndr, NDR_ERR_CHARCNV,
   609                                        "Bad character conversion");
   610          }
   611          NDR_CHECK(ndr_pull_advance(ndr, length*byte_mul));
   612
   613          return NDR_ERR_SUCCESS;
   614  }
